            <section class="sq-page-block sq-product-section" id="products" draggable="true" data-sq-block data-sq-fluid data-sq-rows="21" data-section-id="products"><button class="sq-block-handle" type="button" aria-label="Drag product section"><?= ez_admin_icon('grip') ?></button><header data-sq-element data-sq-element-type="collection-heading" data-layout-desktop="1,1,12,7" data-layout-tablet="1,1,12,7" data-layout-mobile="1,1,12,7"><div><span>Shop the collection</span><h2>Pick one favorite—or build your whole basket.</h2></div><p>Every item stays synchronized with availability, secure payment, and the right fulfillment flow.</p></header><div class="sq-product-grid" data-sq-element data-sq-element-type="product-grid" data-layout-desktop="1,8,12,14" data-layout-tablet="1,8,12,28" data-layout-mobile="1,8,12,42" data-sq-product-grid>
              <article data-product-card="granola"><?= ez_admin_product_art('Granola Madu Nusantara') ?><div><small>Breakfast · 320 g</small><h3>Granola Madu Nusantara</h3><p>Honey-toasted oats, cashews, and warm local spice.</p><footer><b>Rp58.000</b><button type="button">Add to cart</button></footer></div></article>
              <article data-product-card="coffee"><?= ez_admin_product_art('Kopi Susu Concentrate') ?><div><small>Drinks · 650 ml</small><h3>Kopi Susu Concentrate</h3><p>Rich café-style coffee, balanced and ready in seconds.</p><footer><b>Rp79.000</b><button type="button">Add to cart</button></footer></div></article>
              <article data-product-card="sambal"><?= ez_admin_product_art('Sambal Roa Signature') ?><div><small>Pantry · 260 g</small><h3>Sambal Roa Signature</h3><p>Deep smoke, bright chili, and a savory Manado finish.</p><footer><b>Rp46.000</b><button type="button">Add to cart</button></footer></div></article>
            </div></section>
            <section class="sq-page-block sq-image-story" id="story" draggable="true" data-sq-block data-sq-fluid data-sq-rows="12" data-section-id="image-story"><button class="sq-block-handle" type="button" aria-label="Drag image story section"><?= ez_admin_icon('grip') ?></button><div data-sq-element data-sq-element-type="image" data-layout-desktop="1,1,7,12" data-layout-tablet="1,1,12,6" data-layout-mobile="1,1,12,6"><?= ez_admin_product_art('Granola Madu Nusantara') ?></div><article data-sq-element data-sq-element-type="copy" data-layout-desktop="8,1,5,12" data-layout-tablet="1,7,12,6" data-layout-mobile="1,7,12,6"><span>Image-led storytelling</span><h2>Let the product fill the screen.</h2><p>Use photography as the complete section or pair it with a short story. Image-only layouts are always available, but never forced by default.</p><button type="button">See how it is made</button></article></section>
            <section class="sq-page-block sq-benefit-row" draggable="true" data-sq-block data-sq-fluid data-sq-rows="6" data-section-id="benefits"><button class="sq-block-handle" type="button" aria-label="Drag benefits section"><?= ez_admin_icon('grip') ?></button><article data-sq-element data-sq-element-type="benefit" data-layout-desktop="1,1,4,6" data-layout-tablet="1,1,4,6" data-layout-mobile="1,1,12,2"><?= ez_admin_icon('star') ?><div><b>Clear product details</b><small>Know exactly what you will receive</small></div></article><article data-sq-element data-sq-element-type="benefit" data-layout-desktop="5,1,4,6" data-layout-tablet="5,1,4,6" data-layout-mobile="1,3,12,2"><?= ez_admin_icon('credit-card') ?><div><b>Secure payment</b><small>Checkout details verified by Ezkart</small></div></article><article data-physical-only data-sq-element data-sq-element-type="benefit" data-layout-desktop="9,1,4,6" data-layout-tablet="9,1,4,6" data-layout-mobile="1,5,12,2"><?= ez_admin_icon('truck') ?><div><b>Delivery arranged</b><small>Courier, live rate, and ETA at checkout</small></div></article></section>
            <section class="sq-page-block sq-cart-section" draggable="true" data-sq-block data-sq-fluid data-sq-rows="12" data-section-id="checkout"><button class="sq-block-handle" type="button" aria-label="Drag checkout section"><?= ez_admin_icon('grip') ?></button><div data-sq-element data-sq-element-type="copy" data-layout-desktop="1,1,6,12" data-layout-tablet="1,1,12,5" data-layout-mobile="1,1,12,5"><span>Your basket</span><h2>One checkout for every product on the page.</h2><p>Customers can combine products, choose quantities, and pay once through Ezkart's secure checkout.</p></div><aside data-sq-element data-sq-element-type="checkout" data-layout-desktop="8,2,5,10" data-layout-tablet="1,6,12,7" data-layout-mobile="1,6,12,7"><small>Example basket</small><ul data-sq-basket-lines><li data-product-line="granola"><span>Granola Madu Nusantara</span><b>Rp58.000</b></li><li data-product-line="coffee"><span>Kopi Susu Concentrate</span><b>Rp79.000</b></li><li data-product-line="sambal"><span>Sambal Roa Signature</span><b>Rp46.000</b></li></ul><footer><span>Total</span><strong data-sq-basket-total>Rp183.000</strong></footer><button type="button">Continue to secure checkout</button><em><?= ez_admin_icon('shield') ?> Secure checkout powered by Ezkart</em></aside></section>
            <section class="sq-page-block sq-shipping-section" id="shipping" data-physical-only draggable="true" data-sq-block data-sq-fluid data-sq-rows="5" data-section-id="shipping"><button class="sq-block-handle" type="button" aria-label="Drag shipping section"><?= ez_admin_icon('grip') ?></button><span data-sq-element data-sq-element-type="icon" data-layout-desktop="1,1,1,5" data-layout-tablet="1,1,2,5" data-layout-mobile="1,1,2,5"><?= ez_admin_icon('truck') ?></span><div data-sq-element data-sq-element-type="copy" data-layout-desktop="2,1,7,5" data-layout-tablet="3,1,10,3" data-layout-mobile="3,1,10,3"><small>Ezkart fulfillment</small><h2>From page visit to delivered order.</h2><p>Address collection, product weights, courier quotes, payment state, and fulfillment stay connected in one flow.</p></div><ul data-sq-element data-sq-element-type="list" data-layout-desktop="9,1,4,5" data-layout-tablet="3,4,10,2" data-layout-mobile="3,4,10,2"><li>JNE REG</li><li>SiCepat REG</li><li>J&amp;T EZ</li></ul></section>
          </article>
