        <section class="sq-background-manager sq-section-background-manager" data-sq-background-manager="section" data-sq-section-controls><div class="sq-inspector-heading"><h3>Section background</h3><span data-sq-section-background-name>This section</span></div><span class="sq-control-label">Background type</span><div class="sq-style-segmented sq-section-background-type" role="group" aria-label="Section background type"><button type="button" data-sq-section-background-type="solid">Solid color</button><button type="button" data-sq-section-background-type="gradient">Gradient</button><button type="button" data-sq-section-background-type="image">Image</button></div><div class="sq-section-background-solid" data-sq-section-background-panel="solid"><label><span>Background color</span><div class="sq-section-background-color"><input type="color" value="#ffffff" data-sq-section-background-color><output data-sq-section-background-color-output>#FFFFFF</output></div></label></div><div class="sq-section-background-gradient" data-sq-section-background-panel="gradient" hidden><div class="sq-gradient-preview" data-sq-gradient-preview aria-hidden="true"></div><label><span>Gradient style</span><select data-sq-gradient="kind"><option value="linear">Linear</option><option value="radial">Radial</option><option value="wash">Soft blend</option></select></label><div class="sq-gradient-area" data-sq-gradient-area hidden><label class="sq-gradient-center-toggle"><input type="checkbox" data-sq-gradient="centered"><span>Center gradient</span></label><label><span>Gradient height</span><input type="range" min="10" max="200" step="1" value="100" data-sq-gradient="height"><output data-sq-gradient-output="height">100%</output></label></div><div class="sq-gradient-colors"><label><span>First color</span><input type="color" data-sq-gradient="from" value="#ff8430"><output data-sq-gradient-output="from">#FF8430</output></label><label><span>Second color</span><input type="color" data-sq-gradient="to" value="#f82177"><output data-sq-gradient-output="to">#F82177</output></label><label><span>Base color</span><input type="color" data-sq-gradient="base" value="#ffffff"><output data-sq-gradient-output="base">#FFFFFF</output></label></div><label data-sq-gradient-angle><span>Angle</span><input type="range" min="0" max="360" value="135" data-sq-gradient="angle"><output data-sq-gradient-output="angle">135°</output></label><label><span>Color strength</span><input type="range" min="0" max="100" step="1" value="100" data-sq-gradient="opacity"><output data-sq-gradient-output="opacity">100%</output></label><div data-sq-gradient-center hidden><label><span>Horizontal center</span><input type="range" min="0" max="100" value="50" data-sq-gradient="x"></label><label><span>Vertical center</span><input type="range" min="0" max="100" value="50" data-sq-gradient="y"></label></div></div><div class="sq-section-background-image" data-sq-section-background-panel="image" hidden><div class="sq-background-state"><span data-sq-background-thumbnail><?= ez_admin_icon('image') ?></span><div><b data-sq-background-title>No background image</b><small data-sq-background-status>Upload an image or paste a URL below.</small></div></div><div class="sq-background-source-row"><label><input type="file" accept="image/png,image/jpeg,image/webp,image/gif,image/avif" data-sq-background-upload="section"><?= ez_admin_icon('image') ?> Upload image</label><button type="button" data-sq-background-edit="section" hidden>Edit image settings</button></div><label><span>Image URL</span><div class="sq-background-url-row"><input type="url" placeholder="https://…" data-sq-background-url="section"><button type="button" data-sq-background-apply="section">Use URL</button></div></label><div class="sq-section-background-motion"><div class="sq-inspector-heading"><h3>Background motion</h3><span>Live on canvas</span></div><label><span>Scroll effect</span><select data-sq-section-background-scroll-effect><option value="none">None</option><option value="parallax">Parallax</option><option value="parallax-reverse">Reverse parallax</option><option value="zoom">Scroll zoom</option></select></label><label><span>Strength</span><input type="range" min="0" max="100" step="1" value="50" data-sq-section-background-scroll-strength><output data-sq-section-background-scroll-strength-output>50%</output></label><label class="sq-image-damping-toggle"><input type="checkbox" data-sq-section-background-scroll-damping checked><i aria-hidden="true"></i><span><b>Damping</b><small>Smooth the image movement while scrolling.</small></span></label></div><button class="sq-background-remove" type="button" data-sq-background-remove="section" hidden>Remove image</button></div></section>
