        <section data-sq-section-controls><div class="sq-inspector-heading"><h3>Responsive spacing</h3><span data-sq-spacing-device>Desktop</span></div><label class="sq-link-spacing"><input type="checkbox" data-sq-link-spacing><span>Link all sides</span></label><div class="sq-spacing-grid"><label><span>Top</span><input type="range" min="0" max="160" value="8" data-sq-spacing="top"><input class="sq-spacing-number" type="number" min="0" max="240" step="1" aria-label="Top padding in pixels" data-sq-spacing-number="top"><output data-sq-spacing-output="top">8</output></label><label><span>Right</span><input type="range" min="0" max="160" value="16" data-sq-spacing="right"><input class="sq-spacing-number" type="number" min="0" max="240" step="1" aria-label="Right padding in pixels" data-sq-spacing-number="right"><output data-sq-spacing-output="right">16</output></label><label><span>Bottom</span><input type="range" min="0" max="160" value="8" data-sq-spacing="bottom"><input class="sq-spacing-number" type="number" min="0" max="240" step="1" aria-label="Bottom padding in pixels" data-sq-spacing-number="bottom"><output data-sq-spacing-output="bottom">8</output></label><label><span>Left</span><input type="range" min="0" max="160" value="16" data-sq-spacing="left"><input class="sq-spacing-number" type="number" min="0" max="240" step="1" aria-label="Left padding in pixels" data-sq-spacing-number="left"><output data-sq-spacing-output="left">16</output></label></div><p class="sq-field-note">Values are saved independently for desktop, tablet, and mobile.</p></section>
        <section data-sq-section-controls><h3>Entrance animation</h3><label><span>Effect</span><select data-sq-animation><option value="none">None</option><option value="fade">Fade in</option><option value="slide-up">Slide up</option><option value="slide-left">Slide from left</option><option value="scale">Soft scale</option></select></label><div class="sq-inline-controls"><label><span>Duration</span><input type="range" min="200" max="1600" step="100" value="600" data-sq-duration><output data-sq-duration-output>600ms</output></label><label><span>Delay</span><input type="range" min="0" max="1000" step="100" value="0" data-sq-delay><output data-sq-delay-output>0ms</output></label></div><label><span>Easing</span><select data-sq-easing><option value="ease-out">Smooth out</option><option value="ease-in-out">Smooth both</option><option value="cubic-bezier(.2,.8,.2,1)">Expressive</option><option value="linear">Linear</option></select></label><button class="sq-replay-button" type="button" data-sq-replay><?= ez_admin_icon('play') ?> Preview page</button></section>
        <section data-sq-section-controls class="sq-section-layout-tools"><div class="sq-inspector-heading"><h3>Section layout</h3></div><div class="sq-section-spacing-actions"><button type="button" data-sq-fit-section>Fit height to content</button><button type="button" data-sq-reset-section-spacing>Reset padding</button></div><p class="sq-field-note">Changes apply to the selected device size.</p><label><span>Content width</span><input type="range" min="720" max="1440" step="40" value="1200" data-sq-content-width><output data-sq-width-output>1200px</output></label></section>
      </div>
      <footer data-sq-section-actions><button type="button" data-sq-duplicate><?= ez_admin_icon('layers') ?> Duplicate</button><button type="button" data-sq-visibility><?= ez_admin_icon('eye') ?> Hide</button><button class="danger" type="button" data-sq-delete aria-label="Delete selected section"><?= ez_admin_icon('trash') ?> Delete</button></footer>
    </aside>
  </div>
</section>

<dialog class="sq-live-preview-dialog" id="landing-preview-dialog">
  <div class="sq-live-preview-shell"><header><div><small>Live page preview</small><h2 data-sq-preview-title>Landing page</h2></div><nav aria-label="Preview size"><button class="active" type="button" data-sq-preview-device="desktop"><?= ez_admin_icon('monitor') ?><span>Desktop · 1440</span></button><button type="button" data-sq-preview-device="tablet"><?= ez_admin_icon('layout') ?><span>Tablet · 768</span></button><button type="button" data-sq-preview-device="mobile"><?= ez_admin_icon('smartphone') ?><span>Mobile · 390</span></button></nav><div><button type="button" data-sq-preview-new-tab><?= ez_admin_icon('globe') ?><span>Open tab</span></button><button type="button" data-sq-preview-close aria-label="Close preview"><?= ez_admin_icon('x') ?></button></div></header><main data-sq-live-preview-stage data-preview-device="desktop"><div class="sq-live-preview-frame"><iframe title="Landing page production preview" sandbox="allow-scripts allow-forms allow-popups allow-top-navigation-by-user-activation" data-sq-live-preview-frame></iframe></div></main></div>
</dialog>

<dialog class="sq-export-dialog" id="html-export-dialog">
  <form method="dialog"><header><span><?= ez_admin_icon('code') ?></span><div><small>Production output</small><h2>Generated landing-page HTML</h2><p>Responsive structure, selected products, spacing, animations, SEO metadata, and checkout hooks are included.</p></div><button value="close" aria-label="Close HTML export"><?= ez_admin_icon('x') ?></button></header><div class="sq-export-summary"><span><?= ez_admin_icon('check-circle') ?> Semantic HTML</span><span><?= ez_admin_icon('check-circle') ?> Responsive CSS</span><span><?= ez_admin_icon('check-circle') ?> Animation CSS</span><span><?= ez_admin_icon('check-circle') ?> Commerce hooks</span></div><textarea readonly spellcheck="false" data-sq-html-output></textarea><footer><small data-sq-html-size>Ready to generate</small><button class="ui-button" type="button" data-sq-copy-html data-ui-icon="copy">Copy HTML</button><button class="primary" type="button" data-sq-download-html><?= ez_admin_icon('download') ?> Download .html</button></footer></form>
</dialog>

<dialog class="sq-component-dialog" data-sq-component-dialog>
  <form method="dialog" data-sq-component-form>
    <header><span><?= ez_admin_icon('code') ?></span><div><small data-sq-component-dialog-context>Create component</small><h2 data-sq-component-dialog-title>New main component</h2><p>Write HTML, CSS, and JavaScript in one sandboxed component.</p></div><button type="button" data-sq-component-close aria-label="Close component editor"><?= ez_admin_icon('x') ?></button></header>
    <section><div class="sq-component-meta"><label><span>Name</span><input name="component_name" maxlength="80" required placeholder="Announcement card"></label><label><span>Description</span><input name="component_description" maxlength="180" placeholder="Optional usage note"></label></div><label class="sq-component-code-field"><span>Component code</span><textarea name="component_code" rows="18" required spellcheck="false"></textarea></label><div class="sq-component-budget"><span><b data-sq-component-size>0 KB</b> of 200 KB</span><span><b data-sq-component-total>0</b> of 20 components</span></div><p class="sq-component-error" data-sq-component-error hidden></p></section>
    <footer><button type="button" data-sq-component-delete hidden><?= ez_admin_icon('trash') ?> Delete main component</button><span></span><button class="ui-button" type="button" data-sq-component-close data-ui-icon="x">Cancel</button><button class="ui-button primary" type="submit" data-sq-component-save data-ui-icon="save">Save component</button></footer>
  </form>
</dialog>

<dialog class="page-creator-dialog" id="builder-templates-dialog" aria-labelledby="builder-templates-title"><form data-builder-templates-form>
  <header><div><h2 id="builder-templates-title">Templates</h2><p>Choose a design for your current project or a new landing page draft.</p></div><button type="button" data-creator-close aria-label="Close"><?= ez_admin_icon('x') ?></button></header>
  <section><div data-template-picker></div></section>
  <footer><button class="ui-button" type="button" data-creator-close data-ui-icon="x">Cancel</button><button class="ui-button primary" type="submit" data-template-choose disabled data-ui-icon="grid">Use template</button></footer>
</form></dialog>

<dialog class="page-creator-dialog sq-template-apply-dialog" id="template-apply-dialog" aria-labelledby="template-apply-title"><form data-template-apply-form>
  <header><div><h2 id="template-apply-title">Use this template</h2><p data-template-apply-caption></p></div><button type="button" data-template-apply-close aria-label="Close"><?= ez_admin_icon('x') ?></button></header>
  <section>
    <fieldset class="sq-template-destinations">
      <legend>Where would you like to use it?</legend>
      <label><input type="radio" name="destination" value="replace" required><span><b>Replace current project</b><small>Replace this page’s design and product selections. Keep its name and URL. You can undo this change.</small></span></label>
      <label><input type="radio" name="destination" value="new" required disabled aria-describedby="template-page-capacity"><span><b>New landing page draft</b><small>Save your current project and open the template as a separate draft.</small></span></label>
    </fieldset>
    <p id="template-page-capacity" data-template-capacity role="status"></p>
    <button class="ui-button" type="button" data-template-check-limit hidden data-ui-icon="refresh">Check again</button>
    <div class="sq-creator-details" data-template-draft-details hidden>
      <label><span>Page name</span><input name="page_name" required maxlength="60" autocomplete="off" disabled></label>
      <label><span>Free Ezkart URL</span><div class="slug-field"><input name="slug" required maxlength="48" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" autocomplete="off" disabled><em>.ezkart.site</em></div></label>
    </div>
    <p data-template-apply-error role="alert" hidden></p>
  </section>
  <footer><button class="ui-button" type="button" data-template-apply-close data-ui-icon="undo">Back</button><button class="ui-button primary" type="submit" data-template-apply-submit disabled data-ui-icon="grid">Use template</button></footer>
</form></dialog>

<dialog class="page-creator-dialog" id="page-creator-dialog" aria-labelledby="page-creator-title"><form method="dialog" data-page-creator-form>
  <header><div><h2 id="page-creator-title">Create a landing page</h2><p>Choose a design or start blank. Everything is yours to edit.</p></div><button type="button" data-creator-close aria-label="Close"><?= ez_admin_icon('x') ?></button></header>
  <section>
    <div data-template-picker></div>
    <div class="sq-creator-details">
      <label><span>Page name</span><input name="page_name" required maxlength="60" placeholder="Example: Ramadan Collection"></label>
      <label><span>Free Ezkart URL</span><div class="slug-field"><input name="slug" required pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="ramadan-collection"><em>.ezkart.site</em></div></label>
      <div data-template-settings></div>
    </div>
    <details class="sq-creator-optional"><summary>Connect products now (optional)</summary><fieldset data-creator-products><legend>Starting products · optional</legend><p class="creator-products-empty" data-creator-products-empty>You can build your page now and add products later.</p></fieldset></details>
  </section>
  <footer><button class="ui-button" type="button" data-creator-close data-ui-icon="x">Cancel</button><button class="ui-button primary" value="default" data-create-page data-ui-icon="plus">Create &amp; edit</button></footer>
</form></dialog>

<dialog class="sq-favicon-dialog" data-sq-favicon-dialog aria-labelledby="sq-favicon-title" aria-describedby="sq-favicon-description">
  <header><div><h2 id="sq-favicon-title">Add a browser tab icon</h2><p id="sq-favicon-description">Your page has no favicon yet. Add one before publishing, or do it later in Site settings.</p></div><button type="button" data-favicon-close aria-label="Close favicon setup">×</button></header>
  <div class="sq-favicon-dialog-body" data-sq-favicons></div>
  <footer><button class="ui-button" type="button" data-favicon-close>Back to editor</button><button class="ui-button primary" type="button" data-favicon-publish>Publish without favicon</button></footer>
</dialog>
